// Extraer datos de la solicitud del visitante
const body = $input.item.json.body || {};

const popupType = body.type || 'universal';   // scroll_40 | exit_intent | universal
const postUrl = body.postUrl || '';
const postLabels = body.postLabels || [];
const scrollDepth = body.scrollDepth || 0;

return {
  json: {
    popupType,
    postUrl,
    postLabels,
    scrollDepth,
    isClusterPost: postLabels.length > 0,
    isPilar: postLabels.includes('pilar'),
    timestamp: new Date().toISOString()
  }
};

const req = $('Parsear Solicitud').first().json;
const ofertas = $('Ofertas Configuradas').first().json;

const type = req.popupType;

let config = {};

if (type === 'scroll_40') {
  config = {
    active: ofertas.scroll40_active,
    type: 'scroll_40',
    title: ofertas.scroll40_title,
    description: ofertas.scroll40_description,
    ctaText: ofertas.scroll40_ctaText,
    ctaUrl: ofertas.scroll40_ctaUrl,
    bgColor: '#1e3a5f',
    accentColor: '#f59e0b',
    showTimer: false
  };
} else if (type === 'exit_intent') {
  config = {
    active: ofertas.exit_active,
    type: 'exit_intent',
    title: ofertas.exit_title,
    description: ofertas.exit_description,
    ctaText: ofertas.exit_ctaText,
    ctaUrl: ofertas.exit_ctaUrl,
    bgColor: '#7f1d1d',
    accentColor: '#ef4444',
    showTimer: true,
    timerMinutes: 15
  };
} else {
  config = {
    active: ofertas.universal_active,
    type: 'universal',
    title: ofertas.universal_title,
    description: ofertas.universal_description,
    ctaText: ofertas.universal_ctaText,
    ctaUrl: ofertas.universal_ctaUrl,
    bgColor: '#064e3b',
    accentColor: '#10b981',
    showTimer: false
  };
}

return { json: config };
